1	import { describe, expect, it } from "vitest";
2	import { AUTOMATION_ACTIONS, RETRYABLE_ACTIONS } from "./actions.js";
3	import { AUTOMATION_CONDITIONS } from "./conditions.js";
4	import { AUTOMATION_REQUIRED_EVENTS, AUTOMATION_TRIGGERS } from "./triggers.js";
5	import {
6		AUTOMATION_ACTION_KEYS,
7		AUTOMATION_CONDITION_KEYS,
8		AUTOMATION_EXECUTION_MODES,
9		AUTOMATION_TRIGGER_KEYS,
10		executionModeOf,
11		triggersForMode,
12		type AutomationParam
13	} from "./types.js";
14	import { buildDefaultParams, getAvailableActions, getAvailableConditions, validateParams } from "./validate.js";
15	import { AUTOMATION_VARIABLES, flowVariables, getAvailableVariables } from "./variables.js";
16	
17	// El catálogo lo consumen la dashboard Y el módulo, y ninguna de las dos puede
18	// detectar sola que está mal escrito: la dashboard pinta un control roto y el
19	// módulo ejecuta lo que le llegue. Estos tests son el único sitio donde una
20	// entrada mal copiada se cae, así que van sobre la COHERENCIA del catálogo, no
21	// sobre valores concretos (que cambiarán).
22	
23	const allParams = (): Array<{ owner: string; param: AutomationParam }> => [
24		...Object.values(AUTOMATION_TRIGGERS).flatMap((d) => d.params.map((param) => ({ owner: `trigger:${d.key}`, param }))),
25		...Object.values(AUTOMATION_CONDITIONS).flatMap((d) =>
26			d.params.map((param) => ({ owner: `condition:${d.key}`, param }))
27		),
28		...Object.values(AUTOMATION_ACTIONS).flatMap((d) => d.params.map((param) => ({ owner: `action:${d.key}`, param })))
29	];
30	
31	describe("coherencia del catálogo", () => {
32		it("la clave del Record coincide con el `key` de cada definición", () => {
33			// Se rompe copiando y pegando una entrada y olvidando cambiar el `key` de
34			// dentro: el módulo busca por la clave del Record y la dashboard enseña la
35			// de dentro, así que la interfaz apunta a una acción y se ejecuta otra.
36			for (const [key, def] of Object.entries(AUTOMATION_TRIGGERS)) expect(def.key).toBe(key);
37			for (const [key, def] of Object.entries(AUTOMATION_CONDITIONS)) expect(def.key).toBe(key);
38			for (const [key, def] of Object.entries(AUTOMATION_ACTIONS)) expect(def.key).toBe(key);
39		});
40	
41		it("están definidas todas las claves declaradas", () => {
42			expect(Object.keys(AUTOMATION_TRIGGERS).sort()).toEqual([...AUTOMATION_TRIGGER_KEYS].sort());
43			expect(Object.keys(AUTOMATION_CONDITIONS).sort()).toEqual([...AUTOMATION_CONDITION_KEYS].sort());
44			expect(Object.keys(AUTOMATION_ACTIONS).sort()).toEqual([...AUTOMATION_ACTION_KEYS].sort());
45		});
46	
47		it("no hay parámetros repetidos dentro de un mismo bloque", () => {
48			const check = (name: string, params: AutomationParam[]) => {
49				const keys = params.map((p) => p.key);
50				expect(new Set(keys).size, `${name} repite un parámetro`).toBe(keys.length);
51			};
52			for (const def of Object.values(AUTOMATION_TRIGGERS)) check(`trigger:${def.key}`, def.params);
53			for (const def of Object.values(AUTOMATION_CONDITIONS)) check(`condition:${def.key}`, def.params);
54			for (const def of Object.values(AUTOMATION_ACTIONS)) check(`action:${def.key}`, def.params);
55		});
56	
57		it("todo `select` trae opciones y su default es una de ellas", () => {
58			for (const { owner, param } of allParams()) {
59				if (param.type !== "select") continue;
60				expect(param.options?.length, `${owner}.${param.key} no tiene opciones`).toBeGreaterThan(0);
61				if (param.default === undefined || param.default === null) continue;
62				const values = new Set(param.options?.map((o) => o.value));
63				const defaults = Array.isArray(param.default) ? param.default : [param.default];
64				for (const value of defaults) {
65					expect(values.has(String(value)), `${owner}.${param.key}: el default no está entre las opciones`).toBe(true);
66				}
67			}
68		});
69	
70		it("sólo los select llevan `multiple`, y sólo los textos `supportsVariables`", () => {
71			for (const { owner, param } of allParams()) {
72				if (param.multiple) expect(param.type, `${owner}.${param.key}`).toBe("select");
73				if (param.supportsVariables) {
74					expect(["text", "long_text"], `${owner}.${param.key}`).toContain(param.type);
75				}
76			}
77		});
78	
79		it("todo `pattern` declarado es una expresión regular válida", () => {
80			for (const { owner, param } of allParams()) {
81				if (!param.pattern) continue;
82				expect(() => new RegExp(param.pattern as string), `${owner}.${param.key}`).not.toThrow();
83			}
84		});
85	
86		it("los rangos declarados son coherentes", () => {
87			for (const { owner, param } of allParams()) {
88				if (param.min !== undefined && param.max !== undefined) {
89					expect(param.min, `${owner}.${param.key}`).toBeLessThanOrEqual(param.max);
90				}
91			}
92		});
93	
94		it("no hay etiquetas vacías: son el fallback cuando falta la traducción", () => {
95			for (const { owner, param } of allParams()) {
96				expect(param.label.trim(), `${owner}.${param.key}`).not.toBe("");
97			}
98			for (const def of [
99				...Object.values(AUTOMATION_TRIGGERS),
100				...Object.values(AUTOMATION_CONDITIONS),
101				...Object.values(AUTOMATION_ACTIONS)
102			]) {
103				expect(def.label.trim(), def.key).not.toBe("");
104				expect(def.description.trim(), def.key).not.toBe("");
105			}
106		});
107	});
108	
109	describe("alcanzabilidad", () => {
110		// Un bloque que ningún disparador puede satisfacer sale en el catálogo, no
111		// aparece nunca en ningún selector y nadie se entera de que sobra.
112		it("toda condición se puede usar con algún disparador", () => {
113			for (const key of AUTOMATION_CONDITION_KEYS) {
114				const usable = AUTOMATION_TRIGGER_KEYS.some((t) => getAvailableConditions(t).some((c) => c.key === key));
115				expect(usable, `la condición ${key} es inalcanzable`).toBe(true);
116			}
117		});
118	
119		it("toda acción se puede usar con algún disparador", () => {
120			for (const key of AUTOMATION_ACTION_KEYS) {
121				const usable = AUTOMATION_TRIGGER_KEYS.some((t) => getAvailableActions(t).some((a) => a.key === key));
122				expect(usable, `la acción ${key} es inalcanzable`).toBe(true);
123			}
124		});
125	
126		it("todo disparador admite al menos una acción", () => {
127			for (const key of AUTOMATION_TRIGGER_KEYS) {
128				expect(getAvailableActions(key).length, `el disparador ${key} no admite ninguna acción`).toBeGreaterThan(0);
129			}
130		});
131	
132		it("«borrar el mensaje» sólo se ofrece cuando hay mensaje", () => {
133			expect(getAvailableActions("message_send").map((a) => a.key)).toContain("delete_message");
134			expect(getAvailableActions("member_join").map((a) => a.key)).not.toContain("delete_message");
135		});
136	
137		it("«dar un rol» no se ofrece cuando no hay miembro", () => {
138			expect(getAvailableActions("member_join").map((a) => a.key)).toContain("add_role");
139			// Al borrarse un canal no hay nadie a quien darle nada.
140			expect(getAvailableActions("channel_delete").map((a) => a.key)).not.toContain("add_role");
141		});
142	
143		it("«su cuenta tenga cierta antigüedad» nace en «Menos de»", () => {
144			// El default importa de verdad: quien añade este bloque quiere filtrar
145			// CUENTAS NUEVAS (raids, multicuentas). Con «Más de», quien no tocaba el
146			// desplegable publicaba lo contrario de lo que quería y la condición era
147			// `false` para siempre, sin ningún error — costó una sesión de diagnóstico.
148			const comparison = AUTOMATION_CONDITIONS.account_age.params.find((p) => p.key === "comparison");
149			expect(comparison?.default).toBe("less");
150		});
151	
152		it("las demás condiciones de umbral siguen naciendo en «Más de»", () => {
153			// El cambio es SÓLO de antigüedad de cuenta: en «longitud del mensaje» o en
154			// un contador, «más de» es lo que la gente busca.
155			for (const key of ["message_length", "counter_compare", "member_age"] as const) {
156				const comparison = AUTOMATION_CONDITIONS[key].params.find((p) => p.key === "comparison");
157				expect(comparison?.default, `${key} cambió de default sin querer`).toBe("more");
158			}
159		});
160	});
161	
162	describe("eventos de Discord", () => {
163		it("AUTOMATION_REQUIRED_EVENTS cubre todos los disparadores y no repite", () => {
164			// Es lo que se pasa al `events: [...]` del módulo. Un evento que falte deja
165			// su handler MUDO, sin error: por eso se deriva y no se escribe a mano.
166			const declared = new Set(AUTOMATION_REQUIRED_EVENTS);
167			expect(declared.size).toBe(AUTOMATION_REQUIRED_EVENTS.length);
168			for (const def of Object.values(AUTOMATION_TRIGGERS)) {
169				for (const event of def.events) {
170					expect(declared.has(event), `falta el evento de ${def.key}`).toBe(true);
171				}
172			}
173		});
174	
175		it("todo disparador declara al menos un evento, salvo los de horario", () => {
176			// Un disparador de evento SIN eventos queda mudo: el core no le enruta
177			// nada y no hay error que lo delate. Por eso este guard.
178			//
179			// La excepción es `schedule`, y es la ÚNICA: no lo alimenta Discord sino el
180			// poller del módulo (`SchedulePoller`). Declararle un evento haría que el
181			// core le mandara tráfico que no sabe atender.
182			for (const def of Object.values(AUTOMATION_TRIGGERS)) {
183				if (def.category === "schedule") {
184					expect(def.events, `${def.key} no debe declarar eventos`).toEqual([]);
185					continue;
186				}
187				expect(def.events.length, def.key).toBeGreaterThan(0);
188			}
189		});
190	
191		it("`member_activity` provee user+member y sus eventos entran en AUTOMATION_REQUIRED_EVENTS", () => {
192			// Es el disparador que más eventos junta de golpe (mensajes, reacciones,
193			// voz, hilos): el que mejor delata un `events` copiado a medias o uno que
194			// se quedó fuera de `AUTOMATION_REQUIRED_EVENTS`.
195			const def = AUTOMATION_TRIGGERS.member_activity;
196			expect(def.provides).toEqual(["user", "member"]);
197			for (const event of def.events) {
198				expect(AUTOMATION_REQUIRED_EVENTS, event).toContain(event);
199			}
200		});
201	});
202	
203	describe("variables", () => {
204		it("no se ofrece {message} con un disparador que no trae mensaje", () => {
205			const tokens = getAvailableVariables("member_join").map((v) => v.token);
206			expect(tokens).toContain("{user}");
207			expect(tokens).not.toContain("{message}");
208		});
209	
210		it("las variables sin contexto están siempre", () => {
211			const always = AUTOMATION_VARIABLES.filter((v) => v.requires === null).map((v) => v.token);
212			for (const key of AUTOMATION_TRIGGER_KEYS) {
213				const tokens = getAvailableVariables(key).map((v) => v.token);
214				for (const token of always) expect(tokens, key).toContain(token);
215			}
216		});
217	
218		it("no hay tokens repetidos", () => {
219			const tokens = AUTOMATION_VARIABLES.map((v) => v.token);
220			expect(new Set(tokens).size).toBe(tokens.length);
221		});
222	});
223	
224	describe("buildDefaultParams", () => {
225		const allDefs = () => [
226			...Object.values(AUTOMATION_TRIGGERS),
227			...Object.values(AUTOMATION_CONDITIONS),
228			...Object.values(AUTOMATION_ACTIONS)
229		];
230	
231		it("ningún valor de fábrica está mal formado", () => {
232			// Un default inválido es especialmente traicionero: el bloque nace roto y
233			// el usuario ve un error en un campo que no ha tocado nunca.
234			//
235			// `missing_required` se excluye A PROPÓSITO: un bloque recién añadido con
236			// un campo obligatorio DEBE nacer vacío para que el formulario lo pinte y
237			// se lo pida. Lo que no puede es nacer con un valor con formato, rango u
238			// opción imposibles.
239			for (const def of allDefs()) {
240				const issues = validateParams(buildDefaultParams(def.params), def.params, "params").filter(
241					(i) => i.code !== "missing_required"
242				);
243				expect(issues, `${def.key}: ${JSON.stringify(issues)}`).toEqual([]);
244			}
245		});
246	
247		it("sólo quedan sin rellenar los obligatorios que no declaran default", () => {
248			// El complemento del test anterior: sin esto, un default mal escrito que
249			// dejase el campo vacío se colaría disfrazado de «obligatorio sin default».
250			for (const def of allDefs()) {
251				const params = buildDefaultParams(def.params);
252				const missing = validateParams(params, def.params, "params")
253					.filter((i) => i.code === "missing_required")
254					.map((i) => i.path.replace("params.", ""));
255				for (const key of missing) {
256					const param = def.params.find((p) => p.key === key);
257					expect(param?.required, `${def.key}.${key}`).toBe(true);
258					expect(param?.default, `${def.key}.${key} declara un default que no rellena nada`).toBeUndefined();
259				}
260			}
261		});
262	});
263	
264	describe("modo de ejecución", () => {
265		it("executionModeOf deriva los tres modos por la clave del disparador", () => {
266			expect(executionModeOf("on_interval")).toBe("interval");
267			expect(executionModeOf("on_schedule")).toBe("schedule");
268			expect(executionModeOf("member_join")).toBe("always");
269		});
270	
271		it("triggersForMode con el modo `interval` devuelve exactamente on_interval", () => {
272			expect(triggersForMode("interval").map((t) => t.key)).toEqual(["on_interval"]);
273		});
274	
275		it("triggersForMode con el modo `always` deja fuera los de horario y trae los de estadística", () => {
276			const keys = triggersForMode("always").map((t) => t.key);
277			expect(keys).not.toContain("on_interval");
278			expect(keys).not.toContain("on_schedule");
279			expect(keys).toContain("member_count_changed");
280			expect(keys).toContain("voice_count_changed");
281		});
282	
283		it("los tres modos reparten el catálogo entero, sin huecos ni duplicados", () => {
284			const byMode = AUTOMATION_EXECUTION_MODES.flatMap((mode) => triggersForMode(mode));
285			expect(byMode.map((t) => t.key).sort()).toEqual([...AUTOMATION_TRIGGER_KEYS].sort());
286		});
287	});
288	
289	describe("acciones de estadística", () => {
290		it("count_voice_members, count_members y count_role_members guardan su dato con el patrón compartido de save_as", () => {
291			for (const key of ["count_voice_members", "count_members", "count_role_members"] as const) {
292				const saveAs = AUTOMATION_ACTIONS[key].params.find((p) => p.key === "save_as");
293				expect(saveAs, key).toBeDefined();
294				expect(saveAs?.pattern, key).toBe("^[a-z0-9_]{1,32}$");
295				expect(saveAs?.required, key).toBe(true);
296			}
297		});
298	
299		it("count_role_members declara roles, scope y save_as en ese orden, y se puede reintentar", () => {
300			const def = AUTOMATION_ACTIONS.count_role_members;
301			expect(def.params.map((p) => p.key)).toEqual(["roles", "scope", "save_as"]);
302	
303			const roles = def.params.find((p) => p.key === "roles");
304			expect(roles?.type).toBe("role_list");
305			expect(roles?.required).toBe(true);
306	
307			const scope = def.params.find((p) => p.key === "scope");
308			expect(scope?.type).toBe("select");
309			expect(scope?.required).toBe(true);
310			expect(scope?.default).toBe("guild");
311			// Exactamente las tres opciones del contrato — ni una de más ni de menos.
312			// El motor las distingue por su `value`: cambiar uno aquí sin tocar
313			// `ActionRunner` deja el contador midiendo otra cosa en silencio.
314			expect(scope?.options).toEqual([
315				{ value: "guild", label: "En todo el servidor" },
316				{ value: "voice", label: "Sólo los conectados a voz" },
317				{ value: "online", label: "Sólo los que están en línea" }
318			]);
319	
320			// Sólo lee la caché: reintentarla tras un 429 no puede duplicar nada.
321			expect(RETRYABLE_ACTIONS.has("count_role_members")).toBe(true);
322		});
323	});
324	
325	describe("flowVariables", () => {
326		it("ignora las acciones sin save_as y no repite variables", () => {
327			const actions: Array<{ type: string; params?: Record<string, unknown> }> = [
328				{ type: "count_voice_members", params: { save_as: "personas_en_voz" } },
329				{ type: "send_message", params: { channel: "1", content: "hola" } },
330				{ type: "count_voice_members", params: { save_as: "personas_en_voz" } },
331				{ type: "count_members", params: { save_as: "miembros" } }
332			];
333			expect(flowVariables(actions)).toEqual(["personas_en_voz", "miembros"]);
334		});
335	
336		it("sin ninguna acción con save_as no hay variables de flujo", () => {
337			expect(flowVariables([{ type: "send_message", params: { channel: "1", content: "hola" } }])).toEqual([]);
338		});
339	});
340

