import { describe, expect, it } from "vitest";
import { AUTOMATION_ACTIONS, RETRYABLE_ACTIONS } from "./actions.js";
import { AUTOMATION_CONDITIONS } from "./conditions.js";
import { AUTOMATION_REQUIRED_EVENTS, AUTOMATION_TRIGGERS } from "./triggers.js";
import {
	AUTOMATION_ACTION_KEYS,
	AUTOMATION_CONDITION_KEYS,
	AUTOMATION_EXECUTION_MODES,
	AUTOMATION_TRIGGER_KEYS,
	executionModeOf,
	triggersForMode,
	type AutomationParam
} from "./types.js";
import { buildDefaultParams, getAvailableActions, getAvailableConditions, validateParams } from "./validate.js";
import { AUTOMATION_VARIABLES, flowVariables, getAvailableVariables } from "./variables.js";

// El catálogo lo consumen la dashboard Y el módulo, y ninguna de las dos puede
// detectar sola que está mal escrito: la dashboard pinta un control roto y el
// módulo ejecuta lo que le llegue. Estos tests son el único sitio donde una
// entrada mal copiada se cae, así que van sobre la COHERENCIA del catálogo, no
// sobre valores concretos (que cambiarán).

const allParams = (): Array<{ owner: string; param: AutomationParam }> => [
	...Object.values(AUTOMATION_TRIGGERS).flatMap((d) => d.params.map((param) => ({ owner: `trigger:${d.key}`, param }))),
	...Object.values(AUTOMATION_CONDITIONS).flatMap((d) =>
		d.params.map((param) => ({ owner: `condition:${d.key}`, param }))
	),
	...Object.values(AUTOMATION_ACTIONS).flatMap((d) => d.params.map((param) => ({ owner: `action:${d.key}`, param })))
];

describe("coherencia del catálogo", () => {
	it("la clave del Record coincide con el `key` de cada definición", () => {
		// Se rompe copiando y pegando una entrada y olvidando cambiar el `key` de
		// dentro: el módulo busca por la clave del Record y la dashboard enseña la
		// de dentro, así que la interfaz apunta a una acción y se ejecuta otra.
		for (const [key, def] of Object.entries(AUTOMATION_TRIGGERS)) expect(def.key).toBe(key);
		for (const [key, def] of Object.entries(AUTOMATION_CONDITIONS)) expect(def.key).toBe(key);
		for (const [key, def] of Object.entries(AUTOMATION_ACTIONS)) expect(def.key).toBe(key);
	});

	it("están definidas todas las claves declaradas", () => {
		expect(Object.keys(AUTOMATION_TRIGGERS).sort()).toEqual([...AUTOMATION_TRIGGER_KEYS].sort());
		expect(Object.keys(AUTOMATION_CONDITIONS).sort()).toEqual([...AUTOMATION_CONDITION_KEYS].sort());
		expect(Object.keys(AUTOMATION_ACTIONS).sort()).toEqual([...AUTOMATION_ACTION_KEYS].sort());
	});

	it("no hay parámetros repetidos dentro de un mismo bloque", () => {
		const check = (name: string, params: AutomationParam[]) => {
			const keys = params.map((p) => p.key);
			expect(new Set(keys).size, `${name} repite un parámetro`).toBe(keys.length);
		};
		for (const def of Object.values(AUTOMATION_TRIGGERS)) check(`trigger:${def.key}`, def.params);
		for (const def of Object.values(AUTOMATION_CONDITIONS)) check(`condition:${def.key}`, def.params);
		for (const def of Object.values(AUTOMATION_ACTIONS)) check(`action:${def.key}`, def.params);
	});

	it("todo `select` trae opciones y su default es una de ellas", () => {
		for (const { owner, param } of allParams()) {
			if (param.type !== "select") continue;
			expect(param.options?.length, `${owner}.${param.key} no tiene opciones`).toBeGreaterThan(0);
			if (param.default === undefined || param.default === null) continue;
			const values = new Set(param.options?.map((o) => o.value));
			const defaults = Array.isArray(param.default) ? param.default : [param.default];
			for (const value of defaults) {
				expect(values.has(String(value)), `${owner}.${param.key}: el default no está entre las opciones`).toBe(true);
			}
		}
	});

	it("sólo los select llevan `multiple`, y sólo los textos `supportsVariables`", () => {
		for (const { owner, param } of allParams()) {
			if (param.multiple) expect(param.type, `${owner}.${param.key}`).toBe("select");
			if (param.supportsVariables) {
				expect(["text", "long_text"], `${owner}.${param.key}`).toContain(param.type);
			}
		}
	});

	it("todo `pattern` declarado es una expresión regular válida", () => {
		for (const { owner, param } of allParams()) {
			if (!param.pattern) continue;
			expect(() => new RegExp(param.pattern as string), `${owner}.${param.key}`).not.toThrow();
		}
	});

	it("los rangos declarados son coherentes", () => {
		for (const { owner, param } of allParams()) {
			if (param.min !== undefined && param.max !== undefined) {
				expect(param.min, `${owner}.${param.key}`).toBeLessThanOrEqual(param.max);
			}
		}
	});

	it("no hay etiquetas vacías: son el fallback cuando falta la traducción", () => {
		for (const { owner, param } of allParams()) {
			expect(param.label.trim(), `${owner}.${param.key}`).not.toBe("");
		}
		for (const def of [
			...Object.values(AUTOMATION_TRIGGERS),
			...Object.values(AUTOMATION_CONDITIONS),
			...Object.values(AUTOMATION_ACTIONS)
		]) {
			expect(def.label.trim(), def.key).not.toBe("");
			expect(def.description.trim(), def.key).not.toBe("");
		}
	});
});

describe("alcanzabilidad", () => {
	// Un bloque que ningún disparador puede satisfacer sale en el catálogo, no
	// aparece nunca en ningún selector y nadie se entera de que sobra.
	it("toda condición se puede usar con algún disparador", () => {
		for (const key of AUTOMATION_CONDITION_KEYS) {
			const usable = AUTOMATION_TRIGGER_KEYS.some((t) => getAvailableConditions(t).some((c) => c.key === key));
			expect(usable, `la condición ${key} es inalcanzable`).toBe(true);
		}
	});

	it("toda acción se puede usar con algún disparador", () => {
		for (const key of AUTOMATION_ACTION_KEYS) {
			const usable = AUTOMATION_TRIGGER_KEYS.some((t) => getAvailableActions(t).some((a) => a.key === key));
			expect(usable, `la acción ${key} es inalcanzable`).toBe(true);
		}
	});

	it("todo disparador admite al menos una acción", () => {
		for (const key of AUTOMATION_TRIGGER_KEYS) {
			expect(getAvailableActions(key).length, `el disparador ${key} no admite ninguna acción`).toBeGreaterThan(0);
		}
	});

	it("«borrar el mensaje» sólo se ofrece cuando hay mensaje", () => {
		expect(getAvailableActions("message_send").map((a) => a.key)).toContain("delete_message");
		expect(getAvailableActions("member_join").map((a) => a.key)).not.toContain("delete_message");
	});

	it("«dar un rol» no se ofrece cuando no hay miembro", () => {
		expect(getAvailableActions("member_join").map((a) => a.key)).toContain("add_role");
		// Al borrarse un canal no hay nadie a quien darle nada.
		expect(getAvailableActions("channel_delete").map((a) => a.key)).not.toContain("add_role");
	});

	it("«su cuenta tenga cierta antigüedad» nace en «Menos de»", () => {
		// El default importa de verdad: quien añade este bloque quiere filtrar
		// CUENTAS NUEVAS (raids, multicuentas). Con «Más de», quien no tocaba el
		// desplegable publicaba lo contrario de lo que quería y la condición era
		// `false` para siempre, sin ningún error — costó una sesión de diagnóstico.
		const comparison = AUTOMATION_CONDITIONS.account_age.params.find((p) => p.key === "comparison");
		expect(comparison?.default).toBe("less");
	});

	it("las demás condiciones de umbral siguen naciendo en «Más de»", () => {
		// El cambio es SÓLO de antigüedad de cuenta: en «longitud del mensaje» o en
		// un contador, «más de» es lo que la gente busca.
		for (const key of ["message_length", "counter_compare", "member_age"] as const) {
			const comparison = AUTOMATION_CONDITIONS[key].params.find((p) => p.key === "comparison");
			expect(comparison?.default, `${key} cambió de default sin querer`).toBe("more");
		}
	});
});

describe("eventos de Discord", () => {
	it("AUTOMATION_REQUIRED_EVENTS cubre todos los disparadores y no repite", () => {
		// Es lo que se pasa al `events: [...]` del módulo. Un evento que falte deja
		// su handler MUDO, sin error: por eso se deriva y no se escribe a mano.
		const declared = new Set(AUTOMATION_REQUIRED_EVENTS);
		expect(declared.size).toBe(AUTOMATION_REQUIRED_EVENTS.length);
		for (const def of Object.values(AUTOMATION_TRIGGERS)) {
			for (const event of def.events) {
				expect(declared.has(event), `falta el evento de ${def.key}`).toBe(true);
			}
		}
	});

	it("todo disparador declara al menos un evento, salvo los de horario", () => {
		// Un disparador de evento SIN eventos queda mudo: el core no le enruta
		// nada y no hay error que lo delate. Por eso este guard.
		//
		// La excepción es `schedule`, y es la ÚNICA: no lo alimenta Discord sino el
		// poller del módulo (`SchedulePoller`). Declararle un evento haría que el
		// core le mandara tráfico que no sabe atender.
		for (const def of Object.values(AUTOMATION_TRIGGERS)) {
			if (def.category === "schedule") {
				expect(def.events, `${def.key} no debe declarar eventos`).toEqual([]);
				continue;
			}
			expect(def.events.length, def.key).toBeGreaterThan(0);
		}
	});

	it("`member_activity` provee user+member y sus eventos entran en AUTOMATION_REQUIRED_EVENTS", () => {
		// Es el disparador que más eventos junta de golpe (mensajes, reacciones,
		// voz, hilos): el que mejor delata un `events` copiado a medias o uno que
		// se quedó fuera de `AUTOMATION_REQUIRED_EVENTS`.
		const def = AUTOMATION_TRIGGERS.member_activity;
		expect(def.provides).toEqual(["user", "member"]);
		for (const event of def.events) {
			expect(AUTOMATION_REQUIRED_EVENTS, event).toContain(event);
		}
	});
});

describe("variables", () => {
	it("no se ofrece {message} con un disparador que no trae mensaje", () => {
		const tokens = getAvailableVariables("member_join").map((v) => v.token);
		expect(tokens).toContain("{user}");
		expect(tokens).not.toContain("{message}");
	});

	it("las variables sin contexto están siempre", () => {
		const always = AUTOMATION_VARIABLES.filter((v) => v.requires === null).map((v) => v.token);
		for (const key of AUTOMATION_TRIGGER_KEYS) {
			const tokens = getAvailableVariables(key).map((v) => v.token);
			for (const token of always) expect(tokens, key).toContain(token);
		}
	});

	it("no hay tokens repetidos", () => {
		const tokens = AUTOMATION_VARIABLES.map((v) => v.token);
		expect(new Set(tokens).size).toBe(tokens.length);
	});
});

describe("buildDefaultParams", () => {
	const allDefs = () => [
		...Object.values(AUTOMATION_TRIGGERS),
		...Object.values(AUTOMATION_CONDITIONS),
		...Object.values(AUTOMATION_ACTIONS)
	];

	it("ningún valor de fábrica está mal formado", () => {
		// Un default inválido es especialmente traicionero: el bloque nace roto y
		// el usuario ve un error en un campo que no ha tocado nunca.
		//
		// `missing_required` se excluye A PROPÓSITO: un bloque recién añadido con
		// un campo obligatorio DEBE nacer vacío para que el formulario lo pinte y
		// se lo pida. Lo que no puede es nacer con un valor con formato, rango u
		// opción imposibles.
		for (const def of allDefs()) {
			const issues = validateParams(buildDefaultParams(def.params), def.params, "params").filter(
				(i) => i.code !== "missing_required"
			);
			expect(issues, `${def.key}: ${JSON.stringify(issues)}`).toEqual([]);
		}
	});

	it("sólo quedan sin rellenar los obligatorios que no declaran default", () => {
		// El complemento del test anterior: sin esto, un default mal escrito que
		// dejase el campo vacío se colaría disfrazado de «obligatorio sin default».
		for (const def of allDefs()) {
			const params = buildDefaultParams(def.params);
			const missing = validateParams(params, def.params, "params")
				.filter((i) => i.code === "missing_required")
				.map((i) => i.path.replace("params.", ""));
			for (const key of missing) {
				const param = def.params.find((p) => p.key === key);
				expect(param?.required, `${def.key}.${key}`).toBe(true);
				expect(param?.default, `${def.key}.${key} declara un default que no rellena nada`).toBeUndefined();
			}
		}
	});
});

describe("modo de ejecución", () => {
	it("executionModeOf deriva los tres modos por la clave del disparador", () => {
		expect(executionModeOf("on_interval")).toBe("interval");
		expect(executionModeOf("on_schedule")).toBe("schedule");
		expect(executionModeOf("member_join")).toBe("always");
	});

	it("triggersForMode con el modo `interval` devuelve exactamente on_interval", () => {
		expect(triggersForMode("interval").map((t) => t.key)).toEqual(["on_interval"]);
	});

	it("triggersForMode con el modo `always` deja fuera los de horario y trae los de estadística", () => {
		const keys = triggersForMode("always").map((t) => t.key);
		expect(keys).not.toContain("on_interval");
		expect(keys).not.toContain("on_schedule");
		expect(keys).toContain("member_count_changed");
		expect(keys).toContain("voice_count_changed");
	});

	it("los tres modos reparten el catálogo entero, sin huecos ni duplicados", () => {
		const byMode = AUTOMATION_EXECUTION_MODES.flatMap((mode) => triggersForMode(mode));
		expect(byMode.map((t) => t.key).sort()).toEqual([...AUTOMATION_TRIGGER_KEYS].sort());
	});
});

describe("acciones de estadística", () => {
	it("count_voice_members, count_members y count_role_members guardan su dato con el patrón compartido de save_as", () => {
		for (const key of ["count_voice_members", "count_members", "count_role_members"] as const) {
			const saveAs = AUTOMATION_ACTIONS[key].params.find((p) => p.key === "save_as");
			expect(saveAs, key).toBeDefined();
			expect(saveAs?.pattern, key).toBe("^[a-z0-9_]{1,32}$");
			expect(saveAs?.required, key).toBe(true);
		}
	});

	it("count_role_members declara roles, scope y save_as en ese orden, y se puede reintentar", () => {
		const def = AUTOMATION_ACTIONS.count_role_members;
		expect(def.params.map((p) => p.key)).toEqual(["roles", "scope", "save_as"]);

		const roles = def.params.find((p) => p.key === "roles");
		expect(roles?.type).toBe("role_list");
		expect(roles?.required).toBe(true);

		const scope = def.params.find((p) => p.key === "scope");
		expect(scope?.type).toBe("select");
		expect(scope?.required).toBe(true);
		expect(scope?.default).toBe("guild");
		// Exactamente las tres opciones del contrato — ni una de más ni de menos.
		// El motor las distingue por su `value`: cambiar uno aquí sin tocar
		// `ActionRunner` deja el contador midiendo otra cosa en silencio.
		expect(scope?.options).toEqual([
			{ value: "guild", label: "En todo el servidor" },
			{ value: "voice", label: "Sólo los conectados a voz" },
			{ value: "online", label: "Sólo los que están en línea" }
		]);

		// Sólo lee la caché: reintentarla tras un 429 no puede duplicar nada.
		expect(RETRYABLE_ACTIONS.has("count_role_members")).toBe(true);
	});
});

describe("flowVariables", () => {
	it("ignora las acciones sin save_as y no repite variables", () => {
		const actions: Array<{ type: string; params?: Record<string, unknown> }> = [
			{ type: "count_voice_members", params: { save_as: "personas_en_voz" } },
			{ type: "send_message", params: { channel: "1", content: "hola" } },
			{ type: "count_voice_members", params: { save_as: "personas_en_voz" } },
			{ type: "count_members", params: { save_as: "miembros" } }
		];
		expect(flowVariables(actions)).toEqual(["personas_en_voz", "miembros"]);
	});

	it("sin ninguna acción con save_as no hay variables de flujo", () => {
		expect(flowVariables([{ type: "send_message", params: { channel: "1", content: "hola" } }])).toEqual([]);
	});
});

import { AUTOMATION_TRIGGERS } from "./triggers.js";

/**
 * Nombre de un evento de dispatch de Discord, como CADENA.
 *
 * NO se usa aquí el enum `DiscordEvents` a propósito, aunque los valores sean
 * idénticos: ese enum importa `@discordjs/ws`, y este catálogo lo consume el
 * NAVEGADOR desde la dashboard. Una sola importación de `@kena/shared` en un
 * componente de cliente arrastra gRPC al bundle, Vite intenta empaquetar `fs` y
 * el optimizador de dependencias se cae ENTERO — con él, la hidratación de
 * todas las páginas, no sólo la de automatizaciones.
 *
 * Por eso `src/automation/` no importa nada: es la condición para poder
 * exportarlo por la subruta `@kena/shared/automation` y que el cliente lo cargue
 * sin traerse medio Node detrás.
 */
export type AutomationDispatchEvent = string;

/**
 * Tipos del CATÁLOGO de automatizaciones — la única fuente de verdad sobre qué
 * disparadores, condiciones y acciones existen.
 *
 * Lo consumen las DOS puntas y por eso vive aquí:
 *
 *  - La **dashboard** pinta el selector y genera el formulario de parámetros de
 *    cada bloque leyendo estas definiciones. No hay un solo formulario escrito a
 *    mano.
 *  - El **automation-module** valida lo que le llega y decide qué ejecutor
 *    llamar.
 *
 * Con 25 acciones × 2 superficies, cualquier otro reparto acaba en deriva. Añadir
 * una acción nueva es tocar UN fichero (`actions.ts`) y escribir su ejecutor en
 * el módulo; la dashboard la recoge sola.
 */

// ─── Contexto de ejecución ────────────────────────────────────────────────────

/**
 * Piezas que puede llevar el «sobre» de una ejecución.
 *
 * Un disparador APORTA algunas (`provides`) y cada condición/acción EXIGE las
 * suyas (`requires`). De ese cruce sale la parte más importante de la UX: al
 * elegir «Entre al servidor» el selector no ofrece «Borrar el mensaje», porque
 * en ese contexto no hay ningún mensaje que borrar.
 *
 * Sin esto la interfaz deja construir automatizaciones que no pueden funcionar y
 * el fallo sólo se ve en producción, cuando ya no hay quien lo relacione.
 */
export type AutomationContextKey =
	| "user"
	| "member"
	| "channel"
	| "message"
	| "role"
	| "emoji"
	| "voice"
	| "thread";

// ─── Parámetros ───────────────────────────────────────────────────────────────

/**
 * Tipo de un parámetro. Decide tres cosas a la vez: qué control pinta la
 * dashboard, cómo se valida el valor y cómo lo lee el módulo.
 */
export type AutomationParamType =
	| "text"
	| "long_text"
	| "number"
	| "boolean"
	| "channel"
	| "channel_list"
	| "category_list"
	| "role"
	| "role_list"
	| "user"
	| "emoji"
	| "duration"
	| "select"
	| "regex"
	| "counter"
	| "automation"
	| "color"
	/** Imagen subida al CDN del bot. La dashboard pinta el campo de subida. */
	| "image"
	/**
	 * Lienzo del editor de imagen avanzado — mismo formato que usa el greeter.
	 * La dashboard pinta el editor de canvas compartido; el valor es el objeto
	 * del lienzo, o `null` si no se ha configurado ninguno.
	 */
	| "image_canvas";

/** Una opción de un parámetro `select`. */
export interface AutomationParamOption {
	value: string;
	/** Etiqueta en castellano; ver la nota de `label` en {@link AutomationParam}. */
	label: string;
}

export interface AutomationParam {
	/** Nombre del campo dentro de `params`. En inglés, como todo identificador. */
	key: string;
	type: AutomationParamType;
	required: boolean;
	/**
	 * Etiqueta en castellano, y es el FALLBACK, no el texto definitivo: la
	 * dashboard pide primero `automation.param.<key>.label` al servicio de i18n y
	 * sólo cae aquí si esa clave no existe.
	 *
	 * Está para que el catálogo funcione el día uno sin depender de dar de alta
	 * 200 traducciones antes de poder probar nada. `t()` devuelve `""` cuando la
	 * clave falta —no lanza—, así que `t(key) || param.label` resuelve solo.
	 */
	label: string;
	/** Ayuda corta bajo el control. Mismo criterio de i18n que `label`. */
	hint?: string;
	/** Opciones de un `select`. Obligatorio para ese tipo. */
	options?: AutomationParamOption[];
	/** El `select` admite varios valores (el valor pasa a ser `string[]`). */
	multiple?: boolean;
	/**
	 * Pista de PRESENTACIÓN para un `select`: sugiere pintarlo como un par de
	 * chips en vez del desplegable de siempre. Es sólo eso, una sugerencia — la
	 * dashboard decide cómo pintar cada control, el catálogo no impone nada.
	 */
	variant?: "chips";
	/** Mínimo de un `number`, o longitud mínima de un `text`. */
	min?: number;
	/** Máximo de un `number`, o longitud máxima de un `text`. */
	max?: number;
	/**
	 * Forma exacta que debe tener un `text`, como fuente de expresión regular
	 * (sin barras). La valida `validateParams` y la dashboard la usa para avisar
	 * en caliente. Ejemplo: una hora `HH:MM`.
	 */
	pattern?: string;
	/** Valor de fábrica cuando el usuario no toca el campo. */
	default?: string | number | boolean | string[] | null;
	/**
	 * El campo admite variables (`{user}`, `{channel}`…). Sólo tiene sentido en
	 * `text` / `long_text`; la dashboard le engancha el autocompletado.
	 */
	supportsVariables?: boolean;
}

// ─── Categorías ───────────────────────────────────────────────────────────────

/** Grupos del selector. Ordenan la lista larga y nada más. */
export type AutomationCategory =
	| "member"
	| "message"
	| "voice"
	| "server"
	| "stats"
	| "schedule"
	| "flow";

/**
 * Categorías de DISPARADOR agrupadas por la pregunta que responden, para que el
 * selector pueda ofrecerlas como pestañas grandes en vez de una lista de 25.
 *
 * `stats` es la que rompe el molde de MEE6: no es «cuando alguien haga algo»
 * sino «vigila este número». Por eso el chip del editor cambia de «ACTIVADOR»
 * a «RECOGER UNA ESTADÍSTICA» según lo elegido — la diferencia se ve de un
 * vistazo en vez de esconderse en el nombre del disparador.
 */
export const AUTOMATION_TRIGGER_GROUPS = [
	{ key: "action", label: "Activador", categories: ["member", "message", "voice"] },
	{ key: "stats", label: "Recoger una estadística", categories: ["stats"] },
	{ key: "schedule", label: "A una hora fija", categories: ["schedule"] },
	{ key: "server", label: "En el servidor", categories: ["server"] }
] as const satisfies ReadonlyArray<{
	key: string;
	label: string;
	categories: ReadonlyArray<AutomationCategory>;
}>;

export type AutomationTriggerGroupKey = (typeof AUTOMATION_TRIGGER_GROUPS)[number]["key"];

/** Grupo al que pertenece una categoría de disparador. */
export const triggerGroupOf = (category: AutomationCategory): AutomationTriggerGroupKey =>
	AUTOMATION_TRIGGER_GROUPS.find((g) => (g.categories as ReadonlyArray<string>).includes(category))?.key ?? "action";

// ─── Definiciones ─────────────────────────────────────────────────────────────

interface AutomationEntryBase {
	category: AutomationCategory;
	/** Etiqueta en castellano; ver la nota de `label` en {@link AutomationParam}. */
	label: string;
	/** Descripción corta para el selector. Mismo criterio de i18n. */
	description: string;
	params: AutomationParam[];
}

export interface AutomationTriggerDef extends AutomationEntryBase {
	key: AutomationTriggerType;
	/**
	 * Evento(s) de Discord que lo alimentan. TODOS tienen que estar declarados en
	 * el `events: [...]` del constructor del módulo: sin eso el core no los
	 * enruta y el handler queda MUERTO, sin ningún error que lo delate.
	 */
	events: AutomationDispatchEvent[];
	/** Piezas de contexto que este disparador pone sobre la mesa. */
	provides: AutomationContextKey[];
}

export interface AutomationConditionDef extends AutomationEntryBase {
	key: AutomationConditionType;
	/** Contexto sin el cual no se puede evaluar. */
	requires: AutomationContextKey[];
	/**
	 * ¿Tiene sentido el interruptor «no»? En casi todas sí («NO tiene el rol»),
	 * pero negar `chance` («el 30% de las veces») no significa nada útil.
	 */
	negatable: boolean;
}

export interface AutomationActionDef extends AutomationEntryBase {
	key: AutomationActionType;
	/** Contexto sin el cual no se puede ejecutar. */
	requires: AutomationContextKey[];
	/**
	 * Permiso de Discord que necesita el BOT (nombre del flag, ej.
	 * `ManageRoles`). La dashboard lo usa para avisar antes de guardar; el módulo
	 * no lo comprueba porque Discord ya contesta con un error claro.
	 */
	permission?: string;
}

// ─── Claves ───────────────────────────────────────────────────────────────────

export const AUTOMATION_TRIGGER_KEYS = [
	// Estadísticas — vigilan un NÚMERO, no una acción concreta.
	"member_count_changed",
	"voice_count_changed",

	// Horario — ninguno nace de un evento de Discord: los despierta el poller
	// del propio módulo.
	"on_schedule",
	"on_interval",

	// Miembros
	"member_join",
	"member_leave",
	"member_role_add",
	"member_role_remove",
	"member_nickname_change",
	"member_profile_change",
	"member_tag_add",
	"member_tag_remove",
	"member_status_add",
	"member_status_remove",
	"member_boost",
	"member_banned",
	"member_unbanned",
	// Mensajes
	"message_send",
	"message_edit",
	"message_delete",
	"custom_command",
	"reaction_add",
	"reaction_remove",
	// Voz e hilos
	"voice_join",
	"voice_leave",
	"voice_move",
	"thread_join",
	// Servidor
	"channel_create",
	"channel_delete",
	"role_create",
	"role_delete",
	"member_activity"
	// NO añadas aquí `scheduled_event_join` sin añadir ANTES el intent
	// `GuildScheduledEvents` a `BOT_INTENTS` (packages/core). Sin el intent,
	// Discord no manda esos eventos y el disparador sale en la dashboard, se
	// puede publicar y NO SE DISPARA NUNCA — el peor fallo posible aquí, porque
	// no hay ningún error que lo delate. Mismo motivo por el que «Use una
	// invitación» tampoco está: le falta un RPC en el gateway.
] as const;

export const AUTOMATION_CONDITION_KEYS = [
	"in_channel",
	"has_role",
	"has_permission",
	"message_contains",
	"message_matches",
	"message_has",
	"message_length",
	"emoji_is",
	"account_age",
	"member_age",
	"is_bot",
	"has_nickname",
	"role_count",
	"counter_compare",
	"time_window",
	"weekday",
	"rate_limit",
	"chance",
	"member_count",
	"voice_count"
] as const;

export const AUTOMATION_ACTION_KEYS = [
	// Mensajería
	"send_message",
	"send_dm",
	"reply_message",
	"send_webhook",
	"add_reaction",
	"delete_message",
	"pin_message",
	// Publica en los servidores que siguen un canal de ANUNCIOS. Sólo Discord
	// sabe si el canal lo es; en uno de texto la llamada falla con 50019.
	"crosspost_message",
	// Mensaje que se mantiene siempre el último del canal. Es la única acción
	// con estado propio: guarda en Redis el id del mensaje que puso la última
	// vez para poder borrarlo al reponerlo.
	"sticky_message",
	// Roles y miembros
	"add_role",
	"remove_role",
	"set_nickname",
	"kick_member",
	"ban_member",
	"timeout_member",
	// Canales
	"create_channel",
	"create_thread",
	"rename_channel",
	"set_slowmode",
	"set_channel_permission",
	// Voz
	"move_voice",
	"voice_mute",
	// Estadísticas — la primera familia de acciones que NO actúa sobre Discord:
	// recoge un dato (cuánta gente hay en voz, cuántos miembros tiene el
	// servidor, cuántos llevan un rol) y lo guarda en una variable de flujo
	// (`save_as`) para que lo usen las acciones de detrás.
	"count_voice_members",
	"count_members",
	"count_role_members",
	// Flujo
	"wait",
	"counter_set",
	"run_automation"
] as const;

export type AutomationTriggerType = (typeof AUTOMATION_TRIGGER_KEYS)[number];
export type AutomationConditionType = (typeof AUTOMATION_CONDITION_KEYS)[number];
export type AutomationActionType = (typeof AUTOMATION_ACTION_KEYS)[number];

// ─── Modo de ejecución ──────────────────────────────────────────────────────

/**
 * Cuándo se ejecuta el flujo — la primera pregunta del editor nuevo, antes
 * incluso de elegir el disparador: «todo el rato» | «cada cierto tiempo» | «a
 * una hora fija».
 *
 * NO es un campo de `DBAutomation`: se DERIVA del disparador elegido. Guardarlo
 * aparte pediría una migración y, peor, dejaría existir un estado imposible que
 * alguien tendría que arbitrar en ejecución — por ejemplo un `on_interval`
 * guardado con modo `always`, que contradice a su propio disparador.
 */
export const AUTOMATION_EXECUTION_MODES = ["always", "interval", "schedule"] as const;
export type AutomationExecutionMode = (typeof AUTOMATION_EXECUTION_MODES)[number];

/**
 * Modo al que pertenece un disparador. Se mira por su CLAVE y no por su
 * `category`: `on_schedule` y `on_interval` comparten la categoría `schedule`
 * (a los dos los despierta el poller, no un evento de Discord) y es justo el
 * modo el que los separa.
 */
export function executionModeOf(trigger: AutomationTriggerType): AutomationExecutionMode {
	switch (trigger) {
		case "on_interval":
			return "interval";
		case "on_schedule":
			return "schedule";
		default:
			return "always";
	}
}

/**
 * Disparadores de un modo, en el orden de `AUTOMATION_TRIGGER_KEYS`. `interval`
 * y `schedule` traen uno solo: elegir el modo ya elige el disparador, sin
 * segundo paso.
 */
export function triggersForMode(mode: AutomationExecutionMode): AutomationTriggerDef[] {
	return AUTOMATION_TRIGGER_KEYS.filter((key) => executionModeOf(key) === mode).map((key) => AUTOMATION_TRIGGERS[key]);
}

import type { AutomationActionDef, AutomationActionType, AutomationParam } from "./types.js";

/**
 * Catálogo de ACCIONES.
 *
 * Todas tienen transporte gRPC en el gateway hoy — está comprobado contra los
 * `.proto`, no supuesto. Si añades una acción nueva, comprueba que su RPC existe
 * ANTES de meterla aquí: el catálogo es lo que la dashboard ofrece, y ofrecer una
 * acción sin transporte es prometer algo que falla en silencio en producción.
 */

/** Motivo para el registro de auditoría de Discord. */
const reasonParam: AutomationParam = {
	key: "reason",
	type: "text",
	required: false,
	label: "Motivo",
	hint: "Aparece en el registro de auditoría de Discord.",
	max: 512,
	supportsVariables: true,
	default: ""
};

/** Borrado diferido del mensaje que envía la acción. 0 = no se borra. */
const deleteAfterParam: AutomationParam = {
	key: "delete_after",
	type: "duration",
	required: false,
	label: "Borrarlo pasados",
	hint: "Segundos. 0 = no se borra.",
	min: 0,
	max: 86_400,
	default: 0
};

/**
 * Nombre de la variable donde la acción guarda el dato que recoge. Comparte
 * patrón y límites en toda la familia `stats`: cualquier acción que declare
 * una variable de flujo usa este mismo param, no uno propio por acción.
 */
const saveAsParam = (defaultName: string): AutomationParam => ({
	key: "save_as",
	type: "text",
	required: true,
	label: "Guardarlo en la variable",
	hint: "Luego se escribe {nombre} en cualquier campo de texto de las acciones de abajo.",
	pattern: "^[a-z0-9_]{1,32}$",
	min: 1,
	max: 32,
	default: defaultName
});

export const AUTOMATION_ACTIONS: Record<AutomationActionType, AutomationActionDef> = {
	// ─── Mensajería ─────────────────────────────────────────────────────────────

	send_message: {
		key: "send_message",
		category: "message",
		label: "Enviar un mensaje",
		description: "Publica un mensaje en el canal que elijas.",

			},
			{
				key: "operation",
				type: "select",
				required: true,
				label: "Operación",
				default: "add",
				options: [
					{ value: "add", label: "Sumar" },
					{ value: "subtract", label: "Restar" },
					{ value: "set", label: "Fijar a" },
					{ value: "reset", label: "Poner a cero" }
				]
			},
			{ key: "value", type: "number", required: false, label: "Valor", min: 0, default: 1 }
		]
	},

	run_automation: {
		key: "run_automation",
		category: "flow",
		label: "Ejecutar otra automatización",
		description: "Encadena otra automatización con el mismo contexto.",
		requires: [],
		params: [{ key: "automation", type: "automation", required: true, label: "Automatización" }]
	}
};

/**
 * Acciones que es SEGURO reintentar cuando Discord contesta con un 429.
 *
 * El criterio es la idempotencia, no la importancia: aplicar dos veces «dale el
 * rol X» deja exactamente el mismo estado que aplicarla una, así que reintentar
 * no puede hacer daño. Enviar un mensaje NO lo es — el reintento publica un
 * segundo mensaje, el usuario recibe el mismo aviso dos veces y no hay forma de
 * recogerlo.
 *
 * Por eso la lista es una ALTA EXPLÍCITA y no una exclusión: al añadir una
 * acción nueva al catálogo, lo seguro por defecto es no reintentarla. Si fuese
 * una lista de excluidas, olvidarse de dar de alta la acción nueva la haría
 * reintentable en silencio, que es el fallo caro.
 *
 * `wait`, `counter_set` y `run_automation` no salen a la red, así que no pueden
 * dar 429 y no pintan nada aquí.
 */
export const RETRYABLE_ACTIONS: ReadonlySet<AutomationActionType> = new Set([
	"add_reaction",
	"pin_message",
	// Idempotente por el lado de Discord: al segundo intento contesta 40033
	// («ya estaba publicado») y el ejecutor lo lee como éxito, así que un
	// reintento no puede publicar dos veces.
	"crosspost_message",
	"add_role",
	"remove_role",
	"set_nickname",
	"timeout_member",
	"set_slowmode",
	"set_channel_permission",
	"move_voice",
	"voice_mute",
	// Sólo leen: repetir «cuenta la gente en voz», «cuenta los miembros» o
	// «cuenta quién tiene un rol» dos veces deja exactamente el mismo estado
	// que una, así que reintentar no puede hacer daño.
	"count_voice_members",
	"count_members",
	"count_role_members"
]);

/** ¿Se puede reintentar esta acción sin duplicar efectos? */
export const isRetryableAction = (type: string): boolean =>
	RETRYABLE_ACTIONS.has(type as AutomationActionType);

