async removeGuildMemberMeta(guildId: string, memberId: string) {
	return this.del(this.guildMemberKey(guildId, memberId));
}

async hasGuildMemberMeta(guildId: string, memberId: string): Promise<boolean> {
	return this.exists(this.guildMemberKey(guildId, memberId));
}

// ------------------ Roles del miembro del servidor ------------------

async getGuildMemberRoles(guildId: string, memberId: string): Promise<string[]> {
	return this.smembers(this.guildMemberRolesKey(guildId, memberId));
}

async addGuildMemberRole(guildId: string, memberId: string, roleId: string) {
	return this.sadd(this.guildMemberRolesKey(guildId, memberId), roleId);
}

async removeGuildMemberRole(guildId: string, memberId: string, roleId: string) {
	return this.srem(this.guildMemberRolesKey(guildId, memberId), roleId);
}

async removeGuildMemberRoles(guildId: string, memberId: string) {
	return this.del(this.guildMemberRolesKey(guildId, memberId));
}

async hasGuildMemberRole(guildId: string, memberId: string, roleId: string): Promise<boolean> {
	return this.sismember(this.guildMemberRolesKey(guildId, memberId), roleId);
}

/**
 * Cuántos miembros cacheados del guild llevan ALGUNO de los roles pedidos —
 * no la intersección. Es la cuenta que alimenta la acción de automatización
 * `count_role_members` (canales contador tipo «VIP: 132» o «En voz con el
 * rol Staff: 4»).
 *
 * Coste real: UNA comprobación (`SMISMEMBER`) por miembro cacheado del
 * guild, canalizada en una sola pasada de `runBatchedPipeline` — nunca un
 * `await` por miembro, que en un guild grande serían miles de viajes de ida
 * y vuelta en serie. `SMISMEMBER` contra una clave que no existe (miembro
 * sin roles cacheados) responde con ceros igual que si no tuviera ninguno de
 * los pedidos: cuenta como 0 sin caso especial y sin romper la cuenta.
 *
 * `SMISMEMBER` es de Redis 6.2 en adelante — el primer sitio del repo que lo
 * usa. La infra va con 7, pero si algún día hay que soportar uno más viejo,
 * el reemplazo es un `SISMEMBER` por rol y miembro, no un `SMEMBERS` por
 * miembro: traerse la lista entera de roles de cada uno para mirar dos es
 * mover mucho más por la red.
 */
async countMembersWithRoles(guildId: string, roleIds: string[]): Promise<number> {
	if (!roleIds.length) return 0;

	const memberIds = await this.getGuildMembers(guildId);
	if (!memberIds.length) return 0;

	let count = 0;
	await this.runBatchedPipeline(memberIds, { concurrency: 2, stopOnError: true }, (p, memberId) => {
		p.smismember(this.guildMemberRolesKey(guildId, memberId), roleIds, (err, hits) => {
			if (err || !hits) return;
			if (hits.includes(1)) count++;
		});
	});

	return count;
}

// ------------------ Servidor - IDs de canales ------------------

async hasChannelId(guildId: string, channelId: string): Promise<boolean> {
	return this.sismember(this.channelsKey(guildId), channelId);
}

/**
 * Cuántos canales tiene cacheados este servidor.
 *
 * Existe para poder distinguir las DOS cosas que hoy significan lo mismo con
 * `hasChannelId(...) === false`: que el canal esté BORRADO, o que la caché de
 * canales de ese servidor esté simplemente FRÍA. Es un SCARD, no un SMEMBERS.
 *
 * La distinción sólo importa a quien vaya a tomar una decisión destructiva
 * sobre la ausencia de un canal —apagar el 24/7 de un servidor, por ejemplo—:
 * ahí «no lo sé» no puede tratarse como «no existe». Ver
 * `music-module/src/shared/voice-target-guard.ts`.
 */
async countChannelIds(guildId: string): Promise<number> {
	return this.scard(this.channelsKey(guildId));
}

async addChannelId(guildId: string, channelId: string): Promise<void> {
	await this.sadd(this.channelsKey(guildId), channelId);
}

async addChannelIds(guildId: string, channelIds: string[]): Promise<void> {
	await this.pipeline((pipeline) => {
		channelIds.forEach((id) => {
			pipeline.sadd(this.channelsKey(guildId), id);
		});
		return pipeline;

import { AUTOMATION_TRIGGERS } from "./triggers.js";
import type { AutomationContextKey, AutomationTriggerType } from "./types.js";

/**
 * Variables que se pueden escribir en los campos de texto de una acción.
 *
 * Cada una declara de qué pieza del contexto sale, así que la lista que ve el
 * usuario depende del disparador que haya elegido: con «Se cree un canal» no hay
 * usuario, y ofrecerle `{user}` sería ofrecerle un hueco vacío.
 */
export interface AutomationVariable {
	/** El texto literal que se escribe, llaves incluidas. */
	token: string;
	/** Pieza de contexto de la que sale. `null` = siempre disponible. */
	requires: AutomationContextKey | null;
	/** Etiqueta en castellano (fallback de i18n, como en el catálogo). */
	label: string;
}

export const AUTOMATION_VARIABLES: AutomationVariable[] = [
	// Siempre disponibles: salen del guild, que toda ejecución tiene.
	{ token: "{server}", requires: null, label: "Nombre del servidor" },
	{ token: "{server_id}", requires: null, label: "ID del servidor" },
	{ token: "{member_count}", requires: null, label: "Número de miembros" },

	{ token: "{user}", requires: "user", label: "Mención del usuario" },
	{ token: "{user_name}", requires: "user", label: "Nombre del usuario" },
	{ token: "{user_id}", requires: "user", label: "ID del usuario" },
	{ token: "{user_avatar}", requires: "user", label: "URL de su avatar" },

	{ token: "{nickname}", requires: "member", label: "Apodo en el servidor" },
	{ token: "{joined_at}", requires: "member", label: "Fecha de entrada" },

	{ token: "{channel}", requires: "channel", label: "Mención del canal" },
	{ token: "{channel_name}", requires: "channel", label: "Nombre del canal" },
	{ token: "{channel_id}", requires: "channel", label: "ID del canal" },

	{ token: "{message}", requires: "message", label: "Contenido del mensaje" },
	{ token: "{message_id}", requires: "message", label: "ID del mensaje" },
	{ token: "{message_link}", requires: "message", label: "Enlace al mensaje" },

	{ token: "{role}", requires: "role", label: "Mención del rol" },
	{ token: "{role_name}", requires: "role", label: "Nombre del rol" },
	{ token: "{role_id}", requires: "role", label: "ID del rol" },

	/** Etiqueta de servidor que lleva puesta, o hueco si no lleva ninguna. */
	{ token: "{tag}", requires: "user", label: "Etiqueta de servidor" },

	/** El estado personalizado que lleva puesto, o hueco si se lo ha quitado. */
	{ token: "{status}", requires: "user", label: "Estado personalizado" },

	{ token: "{emoji}", requires: "emoji", label: "Emoji" },
	{ token: "{voice_channel}", requires: "voice", label: "Canal de voz" },
	/**
	 * Cuánta gente hay AHORA en ese canal de voz, contando a quien acaba de
	 * provocar el evento. Sale del set de Redis del gateway, no de un RPC.
	 */
	{ token: "{voice_count}", requires: "voice", label: "Personas en el canal de voz" },
	{ token: "{thread}", requires: "thread", label: "Mención del hilo" }
];

/** Variables utilizables con un disparador concreto. Alimenta el autocompletado. */
export function getAvailableVariables(trigger: AutomationTriggerType): AutomationVariable[] {
	const provided = new Set<AutomationContextKey>(AUTOMATION_TRIGGERS[trigger].provides);
	return AUTOMATION_VARIABLES.filter((v) => v.requires === null || provided.has(v.requires));
}

// ─── Variables de flujo ─────────────────────────────────────────────────────

/**
 * Además del catálogo fijo de arriba, cualquier acción con un param `save_as`
 * (la familia `stats`: `count_voice_members`, `count_members`) declara una
 * variable NUEVA en tiempo de ejecución, con el nombre que le haya puesto quien
 * monta el flujo.
 *
 * No hay un catálogo estático que las liste como a `AUTOMATION_VARIABLES`:
 * cuáles existen depende de qué acciones haya DELANTE en el flujo, no del
 * disparador. Esto es lo que la dashboard usa para pintar esas fichas; el
 * motor no lo necesita — a él le basta con `ctx.vars` en tiempo de ejecución.
 */
export function flowVariables(actions: ReadonlyArray<{ type: string; params?: Record<string, unknown> }>): string[] {
	const names: string[] = [];
	const seen = new Set<string>();
	for (const { params } of actions) {
		const saveAs = params?.save_as;
		if (typeof saveAs !== "string" || saveAs === "" || seen.has(saveAs)) continue;
		seen.add(saveAs);
		names.push(saveAs);
	}
	return names;
}

