69	/**
70	 * Condiciones que se pueden usar con este disparador: las que no piden nada que
71	 * el disparador no traiga.
72	 *
73	 * Es lo que hace honesto al selector. Sin este filtro, la interfaz deja montar
74	 * «cuando alguien entre al servidor → si el mensaje contiene "hola"», que no
75	 * puede cumplirse nunca y no falla hasta producción.
76	 */
77	export function getAvailableConditions(trigger: AutomationTriggerType): AutomationConditionDef[] {
78		const provided = new Set<AutomationContextKey>(AUTOMATION_TRIGGERS[trigger].provides);
79		return Object.values(AUTOMATION_CONDITIONS).filter((c) => c.requires.every((k) => provided.has(k)));
