import type { DBAutomation } from "../db/schemas/DBGuildSchemas.js";
import { AUTOMATION_ACTIONS } from "./actions.js";
import { AUTOMATION_CONDITIONS } from "./conditions.js";
import { AUTOMATION_TRIGGERS } from "./triggers.js";
import {
	AUTOMATION_ACTION_KEYS,
	AUTOMATION_CONDITION_KEYS,
	AUTOMATION_TRIGGER_KEYS,
	type AutomationActionDef,
	type AutomationActionType,
	type AutomationConditionDef,
	type AutomationConditionType,
	type AutomationContextKey,
	type AutomationParam,
	type AutomationTriggerType
} from "./types.js";

/**
 * Validación de automatizaciones contra el catálogo. La usan las DOS puntas y
 * ése es el punto: la dashboard para no dejar guardar una automatización rota, y
 * el módulo para no ejecutar una que llegue rota de todos modos (un documento
 * viejo, una edición a mano en Mongo, un catálogo recortado).
 *
 * Devuelve una lista de problemas en vez de lanzar: la dashboard los pinta todos
 * a la vez junto a su campo, que es lo que espera quien está montando el flujo.
 */

export type AutomationIssueCode =
	| "unknown_trigger"
	| "unknown_condition"
	| "unknown_action"
	| "missing_required"
	| "invalid_type"
	| "out_of_range"
	| "invalid_format"
	| "unknown_option"
	| "context_missing"
	| "not_negatable"
	| "no_actions"
	/** Una rama que nunca se alcanzaría: hay un «si no» antes que ella. */
	| "unreachable_branch"
	| "empty_name";

export interface AutomationIssue {
	/** Ruta del campo, tal cual la usa la dashboard para anclar el error. */
	path: string;
	code: AutomationIssueCode;
	/** Mensaje en castellano, listo para enseñar. */
	message: string;
}

const SNOWFLAKE = /^\d{17,20}$/;
const COUNTER_NAME = /^[a-zA-Z0-9_-]{1,64}$/;
const HEX_COLOR = /^#?[0-9a-fA-F]{6}$/;

// ─── Guardas de tipo ──────────────────────────────────────────────────────────

export const isAutomationTriggerType = (value: string): value is AutomationTriggerType =>
	(AUTOMATION_TRIGGER_KEYS as readonly string[]).includes(value);

export const isAutomationConditionType = (value: string): value is AutomationConditionType =>
	(AUTOMATION_CONDITION_KEYS as readonly string[]).includes(value);

export const isAutomationActionType = (value: string): value is AutomationActionType =>
	(AUTOMATION_ACTION_KEYS as readonly string[]).includes(value);

// ─── Compatibilidad disparador ↔ bloque ───────────────────────────────────────

/**
 * Condiciones que se pueden usar con este disparador: las que no piden nada que
 * el disparador no traiga.
 *
 * Es lo que hace honesto al selector. Sin este filtro, la interfaz deja montar
 * «cuando alguien entre al servidor → si el mensaje contiene "hola"», que no
 * puede cumplirse nunca y no falla hasta producción.
 */
export function getAvailableConditions(trigger: AutomationTriggerType): AutomationConditionDef[] {
	const provided = new Set<AutomationContextKey>(AUTOMATION_TRIGGERS[trigger].provides);
	return Object.values(AUTOMATION_CONDITIONS).filter((c) => c.requires.every((k) => provided.has(k)));
}

/** Acciones que se pueden usar con este disparador. Mismo criterio. */
export function getAvailableActions(trigger: AutomationTriggerType): AutomationActionDef[] {
	const provided = new Set<AutomationContextKey>(AUTOMATION_TRIGGERS[trigger].provides);
	return Object.values(AUTOMATION_ACTIONS).filter((a) => a.requires.every((k) => provided.has(k)));
}

// ─── Parámetros ───────────────────────────────────────────────────────────────

/** Objeto de parámetros inicial de un bloque recién añadido, con sus defaults. */
export function buildDefaultParams(params: AutomationParam[]): Record<string, unknown> {
	const out: Record<string, unknown> = {};
	for (const param of params) {
		if (param.default !== undefined) {
			out[param.key] = param.default;
			continue;
		}
		// Sin default declarado. Los campos que el formulario pinta como lista
		// necesitan un array desde el principio (si no, el control no sabe qué
		// renderizar); el resto se deja AUSENTE para que `missing_required` lo cace
		// si hacía falta. Un `default: []` en un obligatorio no arreglaría nada y
		// además disfrazaría el hueco — lo vigila `catalog.test.ts`.
		if (param.type.endsWith("_list") || (param.type === "select" && param.multiple)) out[param.key] = [];
		else if (param.type === "boolean") out[param.key] = false;
	}
	return out;
}

/** ¿Cuenta como «sin rellenar»? `false` y `0` NO — son valores legítimos. */
const isEmpty = (value: unknown): boolean =>
	value === undefined || value === null || value === "" || (Array.isArray(value) && value.length === 0);

function checkOne(param: AutomationParam, value: unknown, path: string): AutomationIssue[] {
	const issues: AutomationIssue[] = [];
	const at = `${path}.${param.key}`;
	const fail = (code: AutomationIssueCode, message: string) => issues.push({ path: at, code, message });

	if (isEmpty(value)) {
		if (param.required) fail("missing_required", `«${param.label}» es obligatorio.`);
		return issues;
	}

	switch (param.type) {
		case "text":
		case "long_text":
		case "emoji":
		case "counter":
		case "automation":
		case "regex":
		case "color": {
			if (typeof value !== "string") {
				fail("invalid_type", `«${param.label}» tiene que ser texto.`);
				break;
			}
			if (param.min !== undefined && value.length < param.min) {
				fail("out_of_range", `«${param.label}» necesita al menos ${param.min} caracteres.`);
			}
			if (param.max !== undefined && value.length > param.max) {
				fail("out_of_range", `«${param.label}» admite como mucho ${param.max} caracteres.`);
			}
			if (param.pattern && !new RegExp(param.pattern).test(value)) {
				fail("invalid_format", `«${param.label}» no tiene el formato correcto.`);
			}
			if (param.type === "counter" && !COUNTER_NAME.test(value)) {
				fail("invalid_format", `«${param.label}» sólo admite letras, números, guiones y guiones bajos.`);
			}
			if (param.type === "color" && !HEX_COLOR.test(value)) {
				fail("invalid_format", `«${param.label}» tiene que ser un color hexadecimal, por ejemplo #5865F2.`);
			}
			if (param.type === "regex") {
				try {
					new RegExp(value);
				} catch {
					fail("invalid_format", `«${param.label}» no es una expresión regular válida.`);
				}
			}
			break;
		}

		case "number":
		case "duration": {
			if (typeof value !== "number" || !Number.isFinite(value)) {
				fail("invalid_type", `«${param.label}» tiene que ser un número.`);
				break;
			}
			if (param.min !== undefined && value < param.min) {
				fail("out_of_range", `«${param.label}» no puede bajar de ${param.min}.`);
			}
			if (param.max !== undefined && value > param.max) {
				fail("out_of_range", `«${param.label}» no puede pasar de ${param.max}.`);
			}
			break;
		}

		case "boolean": {
			if (typeof value !== "boolean") fail("invalid_type", `«${param.label}» tiene que ser sí o no.`);
			break;
		}

		case "channel":
		case "role":
		case "user": {
			if (typeof value !== "string" || !SNOWFLAKE.test(value)) {
				fail("invalid_format", `«${param.label}» no es un identificador de Discord válido.`);
			}
			break;
		}

		case "channel_list":
		case "category_list":
		case "role_list": {
			if (!Array.isArray(value)) {
				fail("invalid_type", `«${param.label}» tiene que ser una lista.`);
				break;
			}
			if (value.some((v) => typeof v !== "string" || !SNOWFLAKE.test(v))) {
				fail("invalid_format", `«${param.label}» contiene un identificador de Discord que no es válido.`);
			}
			break;
		}

		case "select": {
			const allowed = new Set((param.options ?? []).map((o) => o.value));
			const values = param.multiple ? value : [value];
			if (param.multiple && !Array.isArray(value)) {
				fail("invalid_type", `«${param.label}» tiene que ser una lista.`);
				break;
			}
			for (const v of values as unknown[]) {
				if (typeof v !== "string" || !allowed.has(v)) {
					fail("unknown_option", `«${param.label}» tiene un valor que no está entre las opciones.`);
					break;
				}
			}
			break;
		}

		case "image_canvas": {
			if (typeof value !== "object" || Array.isArray(value)) {
				fail("invalid_type", `«${param.label}» tiene que ser un lienzo.`);
				break;
			}
			const canvas = value as Record<string, unknown>;
			if (typeof canvas.width !== "number" || typeof canvas.height !== "number") {
				fail("invalid_type", `«${param.label}» necesita un ancho y un alto numéricos.`);
			}
			if (!Array.isArray(canvas.elements)) {
				fail("invalid_type", `«${param.label}» necesita una lista de elementos.`);
			}
			break;
		}
	}

	return issues;
}

/** Valida el objeto `params` de un bloque contra la especificación del catálogo. */
export function validateParams(
	params: Record<string, unknown> | undefined,
	spec: AutomationParam[],
	path: string
): AutomationIssue[] {
	const values = params ?? {};
	return spec.flatMap((param) => checkOne(param, values[param.key], path));
}

// ─── Automatización completa ──────────────────────────────────────────────────

/**
 * Valida una automatización entera. Lista vacía = se puede publicar.
 *
 * El orden importa: si el disparador no se reconoce se para ahí, porque sin
 * saber qué contexto aporta, todos los errores de contexto de abajo serían ruido
 * derivado del primero.
 */
export function validateAutomation(automation: DBAutomation): AutomationIssue[] {
	const issues: AutomationIssue[] = [];

	if (!automation.name?.trim()) {
		issues.push({ path: "name", code: "empty_name", message: "La automatización necesita un nombre." });
	}

	const triggerType = automation.trigger?.type;
	if (!triggerType || !isAutomationTriggerType(triggerType)) {
		issues.push({
			path: "trigger.type",
			code: "unknown_trigger",
			message: "Ese disparador no existe. Puede que se haya retirado del catálogo."
		});
		return issues;
	}

	const trigger = AUTOMATION_TRIGGERS[triggerType];
	const provided = new Set<AutomationContextKey>(trigger.provides);
	issues.push(...validateParams(automation.trigger.params, trigger.params, "trigger.params"));

	issues.push(...validateConditionList(automation.conditions, provided, "conditions"));

	if (!automation.actions || automation.actions.length === 0) {
		issues.push({ path: "actions", code: "no_actions", message: "Añade al menos una acción." });
	}
	issues.push(...validateActionList(automation.actions, provided, "actions"));

	// ── Ramas alternativas ────────────────────────────────────────────────────

	// Sin condición en la raíz, la raíz NUNCA falla: se ejecuta siempre, así que
	// ninguna rama llegaría a mirarse jamás. Se corta aquí, antes de recorrerlas
	// una a una, en vez de dejar que cada rama parezca válida por separado.
	if ((automation.branches?.length ?? 0) > 0 && (automation.conditions?.length ?? 0) === 0) {
		issues.push({
			path: "branches",
			code: "unreachable_branch",
			message:
				"Las ramas sólo tienen sentido con una condición arriba: sin ella el flujo principal se ejecuta siempre y ninguna rama llega a evaluarse."
		});
	}

	const branches = automation.branches ?? [];
	branches.forEach((branch, index) => {
		const at = `branches[${index}]`;

		issues.push(...validateConditionList(branch.conditions, provided, `${at}.conditions`));

		if (!branch.actions || branch.actions.length === 0) {
			issues.push({
				path: `${at}.actions`,
				code: "no_actions",
				message: "Esta rama no hace nada: añade una acción o quítala."
			});
		}
		issues.push(...validateActionList(branch.actions, provided, `${at}.actions`));

		// Una rama SIN condiciones es el «si no» final: pasa siempre, así que todo
		// lo que venga detrás no se ejecutará jamás. Se rechaza al guardar en vez
		// de dejar al usuario descubriendo en producción por qué su última rama no
		// hace nada.
		//
		// El mensaje habla de la vía que FALTA por rellenar y no de la colocación,
		// porque es el estado normal de una vía «si no, si…» recién abierta: nace
		// sin condición, delante del «si no», y lo siguiente que hay que hacer es
		// justo ponérsela.
		const isElse = (branch.conditions?.length ?? 0) === 0;
		if (isElse && index !== branches.length - 1) {
			issues.push({
				path: `${at}.conditions`,
				code: "unreachable_branch",
				message:
					"Esta vía necesita una condición: «si no» es siempre la última, y lo que va detrás de ella no se ejecuta nunca."
			});
		}
	});

	return issues;
}

/** Valida una lista de condiciones contra el contexto del disparador. */
function validateConditionList(
	conditions: DBAutomation["conditions"] | undefined,
	provided: Set<AutomationContextKey>,
	pathPrefix: string
): AutomationIssue[] {
	const issues: AutomationIssue[] = [];
	conditions?.forEach((condition, index) => {
		const at = `${pathPrefix}[${index}]`;
		if (!isAutomationConditionType(condition.type)) {
			issues.push({ path: `${at}.type`, code: "unknown_condition", message: "Esa condición no existe." });
			return;
		}
		const def = AUTOMATION_CONDITIONS[condition.type];
		const missing = def.requires.filter((k) => !provided.has(k));
		if (missing.length > 0) {
			issues.push({
				path: `${at}.type`,
				code: "context_missing",
				message: `«${def.label}» no se puede usar con este disparador: le falta ${missing.join(", ")}.`
			});
		}
		if (condition.negate && !def.negatable) {
			issues.push({
				path: `${at}.negate`,
				code: "not_negatable",
				message: `«${def.label}» no se puede invertir.`
			});
		}
		issues.push(...validateParams(condition.params, def.params, `${at}.params`));
	});
	return issues;
}

/** Valida una lista de acciones contra el contexto del disparador. */
function validateActionList(
	actions: DBAutomation["actions"] | undefined,
	provided: Set<AutomationContextKey>,
	pathPrefix: string
): AutomationIssue[] {
	const issues: AutomationIssue[] = [];
	actions?.forEach((action, index) => {
		const at = `${pathPrefix}[${index}]`;
		if (!isAutomationActionType(action.type)) {
			issues.push({ path: `${at}.type`, code: "unknown_action", message: "Esa acción no existe." });
			return;
		}
		const def = AUTOMATION_ACTIONS[action.type];
		const missing = def.requires.filter((k) => !provided.has(k));
		if (missing.length > 0) {
			issues.push({
				path: `${at}.type`,
				code: "context_missing",
				message: `«${def.label}» no se puede usar con este disparador: le falta ${missing.join(", ")}.`
			});
		}
		issues.push(...validateParams(action.params, def.params, `${at}.params`));
	});
	return issues;
}

